# The contracts filter's gate: what job contracts reads.
GATE = gate("contracts", "contracts", reads=reads(
    ("packages/contracts/**", f"{at('contracts', 'Typecheck contracts')}, test (src/, scripts/gen-go.test.ts) and build in packages/contracts"),
    ("skills/dispatch/SKILL.md", "packages/contracts/src/dispatch-tools.test.ts's dispatchSkillHeadings reads skills/dispatch/SKILL.md headings"),
    ("skills/dispatch-writing-specs/SKILL.md", "`packages/contracts/src/dispatch-tools.test.ts#points dispatch_issue's spec and dispatch_doc_edit at the skill that writes specs` checks existsSync(skills/dispatch-writing-specs/SKILL.md)"),
    (f"{ENVOY}/internal/dispatch/text/testdata/dispatch-href-references.json", "`packages/contracts/src/dispatch-href.test.ts#the Go reader's table is the same table`"),
    (f"{ENVOY}/internal/dispatch/text/testdata/dispatch-text-references.json", "`packages/contracts/src/dispatch-text-references.test.ts#the Go reader's text table is the same table`"),
    (f"{ENVOY}/internal/dispatch/text/testdata/dispatch-block-id-encodings.json", "`packages/contracts/src/dispatch-block-ref.test.ts#the Go encoder's table is the same table` reads the Go side's own table by relative path and asserts set equality against it, so the two halves are one corpus"),
    (f"{DAEMON}/internal/intake/testdata/dispatch/server-started.json", "`packages/contracts/src/dispatch-api.test.ts#the envelope Dispatch publishes for an announcement carries a payload this schema reads` (by a new URL relative to the test)"),
    (f"{ENVOY}/internal/dispatch/pmdoc/testdata/block-pointer-values.json", "`packages/contracts/src/dispatch-block-ref.test.ts#the Go schema's table of block[] values is the same table` reads pmdoc's own JSON copy of the block pointer table by relative path"),
    (f"{ENVOY}/internal/dispatch/pmdoc/testdata/typed-block-id-spellings.json", "`packages/contracts/src/dispatch-block-ref.test.ts#the Go renderer's table of typed block id spellings is the same table` reads pmdoc's own JSON copy of the typed block id spellings by relative path"),
    (f"{ENVOY}/internal/dispatch/pmdoc/testdata/ask-block-scanner.json", "`packages/contracts/src/dispatch-block-ref.test.ts#SCANNER_CORPUS` reads pmdoc's JSON corpus of the two ask block scanners by relative path; `packages/envoy/internal/dispatch/refs/scope_test.go#TestQuestionBlocksReadTheAskBlocksPmdocReads` reads the same file, so the two scanners are held to one corpus"),
    (f"{ENVOY}/internal/contracts/generated.go", "`packages/contracts/scripts/gen-go.test.ts#the committed Go contract is what the generator emits, without a question schema`, `packages/contracts/scripts/gen-go.test.ts#makes --check fail, naming it`, `packages/contracts/scripts/gen-go.test.ts#generated` and `packages/contracts/scripts/gen-go.test.ts#output` reads it for the envelope aliases, each hand-edit row reads every file of generated (this one as output), and gen-go.ts's outputs list holds it (--check compares the committed file)"),
    (f"{ENVOY}/internal/contracts/dispatch_tools_generated.go", "`packages/contracts/src/dispatch-tools.test.ts#the generated Go copy of the tools carries the rule` reads it for the decision-block rule and `packages/contracts/src/dispatch-tools.test.ts#generatedTools` for every tool's Min and Max bounds, `packages/contracts/scripts/gen-go.test.ts#makes --check fail, naming it`, `packages/contracts/scripts/gen-go.test.ts#generated` and `packages/contracts/scripts/gen-go.test.ts#dispatchToolsOutput`: each hand-edit row reads every file of generated (this one as dispatchToolsOutput), and gen-go.ts's outputs list holds it (--check compares the committed file)"),
    (f"{ENVOY}/listenerwire/envelope_generated.go", "`packages/contracts/scripts/gen-go.test.ts#the committed Go contract is what the generator emits, without a question schema`, `packages/contracts/scripts/gen-go.test.ts#makes --check fail, naming it`, `packages/contracts/scripts/gen-go.test.ts#generated` and `packages/contracts/scripts/gen-go.test.ts#envelopeOutput` reads it for the envelope, each hand-edit row reads every file of generated (this one as envelopeOutput), and gen-go.ts's outputs list holds it (the envelope's Go mirror, generated from schemas/envelope.schema.json)"),
    (f"{ENVOY}/internal/dispatch/pmdoc/schema_generated.go", "`packages/contracts/scripts/gen-go.test.ts#makes --check fail, naming it`, `packages/contracts/scripts/gen-go.test.ts#generated` and `packages/contracts/scripts/gen-go.test.ts#blockSchemaOutput`: each hand-edit row reads every file of generated (this one as blockSchemaOutput), and gen-go.ts's outputs list holds it (the block schema's shape, generated from schemas/block-schema.schema.json)"),
    (f"{ENVOY}/internal/contracts/dispatch_frame_generated.go", "`packages/contracts/scripts/gen-go.test.ts#makes --check fail, naming it`, `packages/contracts/scripts/gen-go.test.ts#generated` and `packages/contracts/scripts/gen-go.test.ts#dispatchFrameOutputs`: each hand-edit row reads every file of generated (this one in dispatchFrameOutputs), and gen-go.ts's outputs list holds it (the Dispatch frame schema DispatchPayloadIsEvent checks, rendered by gen-go-dispatch-frame.ts)"),
    (TEST_FIXTURES_SRC, "packages/contracts/src/*.test.ts import @legion/test-fixtures"),
) + install_jj("contracts") + bun_job("contracts"))
